JSON.parse("{\"title\":\"API\",\"description\":\"\",\"frontmatter\":{\"title\":\"API\"},\"headers\":[{\"level\":3,\"title\":\"IxChart\",\"slug\":\"ixchart\",\"link\":\"#ixchart\",\"children\":[]},{\"level\":3,\"title\":\"默认插槽\",\"slug\":\"默认插槽\",\"link\":\"#默认插槽\",\"children\":[]},{\"level\":3,\"title\":\"AdditionalChartOption\",\"slug\":\"additionalchartoption\",\"link\":\"#additionalchartoption\",\"children\":[]},{\"level\":3,\"title\":\"实例访问\",\"slug\":\"实例访问\",\"link\":\"#实例访问\",\"children\":[]},{\"level\":3,\"title\":\"主题与文字样式\",\"slug\":\"主题与文字样式\",\"link\":\"#主题与文字样式\",\"children\":[]},{\"level\":3,\"title\":\"组合式配置函数\",\"slug\":\"组合式配置函数\",\"link\":\"#组合式配置函数\",\"children\":[]},{\"level\":3,\"title\":\"纯配置函数\",\"slug\":\"纯配置函数\",\"link\":\"#纯配置函数\",\"children\":[]},{\"level\":3,\"title\":\"配置合并与更新\",\"slug\":\"配置合并与更新\",\"link\":\"#配置合并与更新\",\"children\":[]},{\"level\":3,\"title\":\"无障碍\",\"slug\":\"无障碍\",\"link\":\"#无障碍\",\"children\":[]},{\"level\":3,\"title\":\"默认图例与提示框样式\",\"slug\":\"默认图例与提示框样式\",\"link\":\"#默认图例与提示框样式\",\"children\":[]},{\"level\":3,\"title\":\"自定义 Tooltip\",\"slug\":\"自定义-tooltip\",\"link\":\"#自定义-tooltip\",\"children\":[]},{\"level\":3,\"title\":\"useChart\",\"slug\":\"usechart\",\"link\":\"#usechart\",\"children\":[]}],\"relativePath\":\"src/components/core/API.md\"}");
